package pro.livemic.studio;

import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import java.io.*;
import java.nio.*;
import java.nio.file.*;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class SessionStoreTest {
    File root,source;SessionStore store;
    @Before public void setup()throws Exception{ExitCoordinator.resetForLaunch();root=Files.createTempDirectory("session-test").toFile();store=new SessionStore(new File(root,"sessions"));source=wav(new File(root,"source.wav"),44100,2,1,16,441);}
    @After public void cleanup()throws Exception{Thread.interrupted();ExitCoordinator.resetForLaunch();if(root!=null)try(java.util.stream.Stream<Path> paths=Files.walk(root.toPath())){paths.sorted(java.util.Comparator.reverseOrder()).forEach(p->{try{Files.delete(p);}catch(IOException ignored){}});}}
    static File wav(File file,int rate,int channels,int format,int bits,int frames)throws Exception{int block=channels*bits/8,data=frames*block;ByteBuffer b=ByteBuffer.allocate(44+data).order(ByteOrder.LITTLE_ENDIAN);b.put("RIFF".getBytes("US-ASCII")).putInt(36+data).put("WAVEfmt ".getBytes("US-ASCII")).putInt(16).putShort((short)format).putShort((short)channels).putInt(rate).putInt(rate*block).putShort((short)block).putShort((short)bits).put("data".getBytes("US-ASCII")).putInt(data);Files.write(file.toPath(),b.array());return file;}
    @Test public void importedMediaSurvivesLegacyDeletionDuplicateAndSessionDeletion()throws Exception{SessionProject p=store.create("Song");SessionProject.Media media=store.importWav(p,source,"legacy","old");store.addAudioClip(p,media,"Voice","VOCAL",960);store.save(p);assertTrue(source.delete());p=store.open(p.id);assertEquals(480,p.clips.get(0).lengthFrames);assertTrue(store.mediaFile(p,p.media.get(0)).exists());SessionProject copy=store.duplicate(p,"Copy");assertNotEquals(p.id,copy.id);assertTrue(store.mediaFile(copy,copy.media.get(0)).exists());store.delete(p.id);assertTrue(store.mediaFile(copy,copy.media.get(0)).exists());assertEquals(1,store.list().size());}
    @Test public void failedManifestUpdatePreservesPriorSaveAndCaptureTarget()throws Exception{SessionProject p=store.create("Song");SessionProject.Media media=store.importWav(p,source,"legacy","old");store.addAudioClip(p,media,"Voice","VOCAL",0);store.save(p);JSONObject target=new JSONObject().put("token","capture_1").put("sessionId",p.id).put("trackId",p.tracks.get(0).id).put("startFrame",0);store.writePendingTarget(p,target);assertEquals("capture_1",store.open(p.id).pendingTarget.getString("token"));try{store.writePendingTarget(p,new JSONObject(target.toString()).put("trackId","missing"));fail();}catch(IllegalArgumentException expected){}assertEquals("capture_1",p.pendingTarget.getString("token"));assertEquals("capture_1",store.open(p.id).pendingTarget.getString("token"));p.clips.get(0).lengthFrames=481;try{store.save(p);fail();}catch(IllegalArgumentException expected){}assertEquals(480,store.open(p.id).clips.get(0).lengthFrames);}
    @Test public void exactWavHeaderSizeRateAndWholeFramesRequired()throws Exception{assertEquals(441,SessionStore.inspectWav(source).frames);File floating=wav(new File(root,"float.wav"),48000,1,3,32,12);assertEquals(3,SessionStore.inspectWav(floating).format);try(RandomAccessFile f=new RandomAccessFile(source,"rw")){f.setLength(f.length()-1);}try{SessionStore.inspectWav(source);fail();}catch(IOException expected){}wav(source,44100,2,1,16,441);try(RandomAccessFile f=new RandomAccessFile(source,"rw")){f.seek(28);f.write(new byte[]{0,0,0,0});}try{SessionStore.inspectWav(source);fail();}catch(IOException expected){}}
    @Test public void traversalInvalidImportAndFailedRenamePreserveExistingSession()throws Exception{SessionProject p=store.create("Song");try{store.open("../takes");fail();}catch(IOException expected){}try{store.rename(p,"");fail();}catch(IllegalArgumentException expected){}assertEquals("Song",store.open(p.id).name);Files.write(source.toPath(),new byte[50]);try{store.importWav(p,source,"legacy","old");fail();}catch(IOException expected){}assertEquals(0,p.media.size());assertEquals(0,store.open(p.id).media.size());}
    @Test public void missingMediaRemainsInManifestAndDoesNotDeleteSource()throws Exception{SessionProject p=store.create("Song");SessionProject.Media media=store.importWav(p,source,"legacy","old");store.addAudioClip(p,media,"Voice","VOCAL",0);store.save(p);assertTrue(store.mediaFile(p,media).delete());assertEquals(1,store.open(p.id).clips.size());assertTrue(source.exists());}
    @Test public void cancelledCopyDoesNotPublishMediaOrLeavePendingFile()throws Exception{SessionProject p=store.create("Song");Thread.currentThread().interrupt();try{store.importWav(p,source,"legacy","old");fail();}catch(InterruptedIOException expected){}finally{Thread.interrupted();}assertEquals(0,p.media.size());File[] copied=new File(store.directory,p.id+"/media").listFiles();assertNotNull(copied);assertEquals(0,copied.length);ExitCoordinator.requestExit();try{store.importWav(p,source,"legacy","old");fail();}catch(InterruptedIOException expected){}assertTrue(source.exists());assertEquals(0,store.open(p.id).media.size());}
    @Test public void harmonyLoopKeepsSourcePeriodAndCoversArrangement()throws Exception{SessionProject p=store.create("Song");p.composer=new ComposerProject();SessionProject.Media m=store.importWav(p,source,"harmony","part");SessionProject.Clip c=store.addAudioClip(p,m,"Harmony","HARMONY",0);long period=c.lengthFrames,arrangement=p.durationFrames();SessionStore.repeatHarmony(p,c);assertTrue(c.loop);assertEquals(period,c.loopLengthFrames);assertEquals(arrangement,c.lengthFrames);p.validate();}
    @Test public void exitDrainPreservesAcceptedEditsAndCaptureJournalWhileBulkImportCancels()throws Exception{
        SessionProject p=store.create("Song");SessionProject.Media m=store.importWav(p,source,"legacy","old");SessionProject.Clip clip=store.addAudioClip(p,m,"Voice","VOCAL",0);store.save(p);byte[] legacy=Files.readAllBytes(source.toPath());
        ExitCoordinator.requestExit();p.composer=new ComposerProject();p.composer.bpm=117;try{store.save(p);fail();}catch(InterruptedIOException expected){}assertNull(store.open(p.id).composer);store.saveFinalization(p);assertEquals(117,store.open(p.id).composer.bpm);
        JSONObject target=new JSONObject().put("token","draining_capture").put("sessionId",p.id).put("trackId",clip.trackId).put("startFrame",240).put("takeId","saved_take");store.writePendingTargetFinalization(p,target);assertEquals("saved_take",store.open(p.id).pendingTarget.getString("takeId"));
        try{store.importWav(p,source,"legacy","old");fail();}catch(InterruptedIOException expected){}assertArrayEquals(legacy,Files.readAllBytes(source.toPath()));assertEquals(1,p.media.size());
        Thread.currentThread().interrupt();try{store.writePendingTargetFinalization(p,null);fail();}catch(InterruptedIOException expected){}finally{Thread.interrupted();}assertEquals("saved_take",p.pendingTarget.getString("takeId"));assertEquals("saved_take",store.open(p.id).pendingTarget.getString("takeId"));
    }
    @Test public void takeLeaseBlocksImportAndExplicitMixedChoiceIsRespected()throws Exception{
        TakeStore takes=new TakeStore(RuntimeEnvironment.getApplication(),false);String id="session_test_"+java.util.UUID.randomUUID().toString();
        java.util.concurrent.CountDownLatch acquired=new java.util.concurrent.CountDownLatch(1),release=new java.util.concurrent.CountDownLatch(1);Thread owner=null;
        try{wav(takes.file(id,".wav"),48000,2,1,16,480);wav(takes.file(id,".vocal.wav"),48000,2,3,32,240);takes.save(id,"Take",.01,false,"",new JSONObject().put("sourceVocalRetained",true));SessionProject p=store.create("Song");
            owner=new Thread(()->{try(TakeRecovery.Lease ignored=takes.lease(id)){acquired.countDown();release.await();}catch(Exception e){throw new RuntimeException(e);}});owner.start();assertTrue(acquired.await(5,java.util.concurrent.TimeUnit.SECONDS));try{store.importTake(p,takes,id,0);fail();}catch(IOException expected){}assertEquals(0,p.media.size());release.countDown();owner.join(5000);assertFalse(owner.isAlive());
            SessionProject.Clip mixed=store.importTake(p,takes,id,0,false);assertEquals("AUDIO",p.track(mixed.trackId).kind);assertEquals(480,mixed.lengthFrames);SessionProject.Clip vocal=store.importTake(p,takes,id,0);assertEquals("VOCAL",p.track(vocal.trackId).kind);assertEquals(240,vocal.lengthFrames);
            while(p.tracks.size()<SessionProject.MAX_AUDIO_TRACKS)p.tracks.add(new SessionProject.Track());SessionProject.Clip attached=store.importTakeToTrack(p,takes,id,mixed.trackId,480);assertEquals(mixed.trackId,attached.trackId);assertEquals(8,p.tracks.size());assertEquals(3,p.clips.size());p.validate();
        }finally{release.countDown();if(owner!=null)owner.join(5000);takes.delete(id);}
    }
}
